import { expect, test } from "@playwright/test";
import { Keypair, Networks, Transaction, TransactionBuilder } from "@stellar/stellar-sdk";
import { EXCHANGE_STAND_IN } from "../../lib/scenarios";
import { closeWith } from "./close-with";
import { HORIZON } from "./testnet";

// The exchange close end to end on testnet: the demo's data entries are removed in a cleanup
// round, then the demo is merged into the API's relay (this run's mediator, generated by
// playwright.config.ts), which forwards the balance to the bundled registry's stand-in with the
// session's id memo, in one transaction the mediator co-signed and the playground checked. The
// spec then reads the stand-in's side from Horizon: a payment from the relay carrying that memo.
// The playground creates the stand-in from its market maker when testnet does not have it.

interface HorizonTransaction {
  hash: string;
  successful: boolean;
  memo_type: string;
  memo?: string;
  envelope_xdr: string;
}

interface HorizonPayment {
  type: string;
  from?: string;
  to?: string;
  asset_type?: string;
  amount?: string;
  transaction_hash: string;
}

const relay = (): string => {
  const secret = process.env.PLAYGROUND_E2E_MEDIATOR_SECRET;
  if (!secret) throw new Error("playwright.config.ts sets the run's mediator");
  return Keypair.fromSecret(secret).publicKey();
};

test("a demo closes into the testnet exchange through the relay, with its memo", async ({
  page,
}) => {
  test.setTimeout(6 * 60_000);
  const { session } = await closeWith(
    page,
    {
      scenarios: [
        { id: "data-entries", params: { count: 2 } },
        { id: "exchange-close", params: {} },
      ],
    },
    "Exchange deposit",
    null,
    relay
  );
  const exchange = session.accounts.exchange;
  expect(exchange?.destination).toBe(EXCHANGE_STAND_IN.address);
  expect(exchange?.memoType).toBe("id");

  // The merge's own transaction: the relay hand-off with the session's id memo.
  const res = await fetch(
    `${HORIZON}/accounts/${session.demoPublic}/transactions?order=desc&limit=1`
  );
  expect(res.ok).toBe(true);
  const [close] = ((await res.json()) as { _embedded: { records: HorizonTransaction[] } })._embedded
    .records;
  expect(close?.successful).toBe(true);
  expect(close?.memo_type).toBe("id");
  expect(close?.memo).toBe(exchange?.memo);
  const tx = TransactionBuilder.fromXDR(close!.envelope_xdr, Networks.TESTNET) as Transaction;
  expect(tx.operations.map((op) => op.type)).toEqual(["accountMerge", "payment"]);
  // Signed by the demo and co-signed by the mediator.
  expect(tx.signatures).toHaveLength(2);

  // The stand-in's side: a payment from the relay in that same transaction.
  const payments = await fetch(
    `${HORIZON}/accounts/${EXCHANGE_STAND_IN.address}/payments?order=desc&limit=50`
  );
  expect(payments.ok).toBe(true);
  const records = ((await payments.json()) as { _embedded: { records: HorizonPayment[] } })
    ._embedded.records;
  const received = records.find((p) => p.transaction_hash === close?.hash);
  expect(received).toEqual(
    expect.objectContaining({
      type: "payment",
      from: relay(),
      to: EXCHANGE_STAND_IN.address,
      asset_type: "native",
    })
  );
  expect(Number(received?.amount)).toBeGreaterThan(0);
});
